printf '%s\n' "$out"
last=$(printf '%s\n' "$out" | tail -n 1)
case "${last%% *}" in
  SWEEP-DONE|SKIP|SWEEP) ;;
  RATE-LIMITED) echo "::error title=RATE-LIMITED::$last"; exit 1 ;;
  *) echo "::error title=sweep failed::${last:-no output}"; exit 1 ;;
esac
